static const char camera_settings_js[] = R"golfcam(// Save image controls to the camera, independently of this browser.
(() => {
  const originalFetch = window.fetch.bind(window);
  const pending = new Set();
  const failures = new Map();
  let report = () => {};
  let busy = false;

  // Existing sliders use fetch without awaiting the result. Track those
  // requests so Save cannot overtake the most recent camera adjustment.
  window.fetch = (input, options) => {
    const url = new URL(typeof input === 'string' ? input : input.url, location.href);
    const request = originalFetch(input, options);
    if (url.origin === location.origin && url.pathname === '/control') {
      const key = url.searchParams.get('var');
      const checked = request.then(response => {
        if (!response.ok) throw new Error('The camera rejected a setting. Adjust it again before saving.');
        failures.delete(key);
        report('Changes are temporary. Click Save Settings to keep them.');
      }).catch(error => {
        failures.set(key, error);
        report(error.message, true);
      });
      pending.add(checked);
      checked.finally(() => pending.delete(checked));
    }
    return request;
  };

  document.addEventListener('DOMContentLoaded', async () => {
    const menu = document.getElementById('menu');
    if (!menu) return;
    const panel = document.createElement('section');
    panel.id = 'saved-settings';
    panel.style.cssText = 'margin:8px 0 14px;line-height:1.4';
    panel.innerHTML = '<div style="display:flex;flex-wrap:wrap;gap:6px">'
      + '<button id="save-settings" type="button" disabled>Save Settings</button>'
      + '<button id="restore-settings" type="button" disabled>Restore Defaults</button></div>'
      + '<p id="settings-message" role="status" aria-live="polite" style="margin:8px 0">Checking saved settings...</p>'
      + '<small>Save keeps image controls after unplugging. Advanced register and clock changes are temporary.</small>';
    menu.prepend(panel);
    const save = document.getElementById('save-settings');
    const restore = document.getElementById('restore-settings');
    const message = document.getElementById('settings-message');
    report = (text, error = false) => {
      message.textContent = text;
      message.style.color = error ? '#ffb3b3' : '';
    };

    async function run(action) {
      if (busy) return;
      busy = true;
      const inputs = [...menu.querySelectorAll('input,select,button')];
      const disabled = inputs.map(el => el.disabled);
      inputs.forEach(el => { el.disabled = true; });
      try {
        await Promise.all([...pending]);
        if (action === 'save' && failures.size) throw new Error('A setting was not applied. Adjust it again or restore defaults before saving.');
        report(action === 'save' ? 'Saving...' : 'Restoring defaults...');
        const response = await originalFetch('/settings/' + action, {method: 'POST', cache: 'no-store'});
        const result = await response.json();
        if (!response.ok) throw new Error(result.message || 'The camera could not save settings.');
        report(result.message);
        if (action === 'defaults') {
          // Reload updates the original page's dependent controls as well.
          sessionStorage.setItem('golfcam-settings-message', result.message);
          location.reload();
        }
      } catch (error) {
        report(error.message || 'Connection lost. Check the camera and try again.', true);
      } finally {
        inputs.forEach((el, i) => { el.disabled = disabled[i]; });
        busy = false;
      }
    }
    save.addEventListener('click', () => run('save'));
    restore.addEventListener('click', () => run('defaults'));
    try {
      const response = await originalFetch('/settings', {cache: 'no-store'});
      if (!response.ok) throw new Error('Could not check saved settings. Refresh to retry.');
      const state = await response.json();
      const framesize = document.getElementById('framesize');
      if (framesize) {
        [...framesize.options].forEach(option => {
          if (Number(option.value) > state.max_framesize) option.disabled = true;
        });
      }
      const notice = sessionStorage.getItem('golfcam-settings-message');
      sessionStorage.removeItem('golfcam-settings-message');
      report(notice || (state.saved ? 'A saved profile will load when the camera restarts.' : 'No saved profile yet. Adjust the image, then click Save Settings.'));
      save.disabled = false;
      restore.disabled = false;
    } catch (error) {
      report(error.message, true);
    }
  });
})();
)golfcam";
